// Fail loudly if state lookup returned no row (replay or expired).
const row = $input.first().json;
const query = $('Webhook').first().json.query || {};
if (!row || !row.code_verifier) {
  throw new Error(`Invalid or expired state '${query.state}'. Restart from /webhook/etsy-connect.`);
}
if (!query.code) throw new Error('Missing ?code from Etsy redirect');
return [{ json: { ...row, code: query.code } }];

// Etsy access tokens are formatted 'user_id.access_token_string'.
// Extract user_id and compute the absolute expiry timestamp.
const tok = $input.first().json;
if (!tok.access_token) throw new Error(`Token exchange failed: ${JSON.stringify(tok)}`);
const userId = tok.access_token.split('.')[0];
const expiresAt = new Date(Date.now() + (tok.expires_in - 60) * 1000).toISOString();
return [{ json: {
  shop_name: $('Validate').item.json.shop_name,
  user_id: userId,
  access_token: tok.access_token,
  refresh_token: tok.refresh_token,
  token_expires: expiresAt
} }];

// Etsy returns either a single Shop object or {results:[Shop, ...]}.
// Pick the first shop and merge with token data.
const raw = $input.first().json;
const shop = Array.isArray(raw.results) ? raw.results[0] : raw;
if (!shop || (!shop.shop_id && !shop.shop_name)) {
  throw new Error(`No Etsy shop found on this user: ${JSON.stringify(raw)}`);
}
const tok = $('Parse Token').item.json;
return [{ json: {
  shop_name:    shop.shop_name || tok.shop_name,
  etsy_shop_id: String(shop.shop_id),
  oauth_token:  tok.access_token,
  refresh_token: tok.refresh_token,
  token_expires: tok.token_expires
} }];
